import { test, expect } from '@playwright/test';
import { setLanguage, openPlansTab } from './plans-helpers';
import { accountRows, loadedRowCount, searchBox, EMPTY_EN } from './plans-read-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Admin Panel — Plans', () => {
  test('Search with no match shows empty-state message in English #ca557707 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');
    await openPlansTab(page);
    await loadedRowCount(page);

    await searchBox(page).fill('zzqqxx-none');
    await expect(page.getByText(EMPTY_EN, { exact: true })).toBeVisible();
    await expect(accountRows(page)).toHaveCount(0);
  });
});
